import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Layering of Pipes and Transport Belts","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"管道及传送带的分层现象","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=feO9v8bYahZcFBLue5rPC3","scope":"page"}},"headers":[],"relativePath":"src/page-feO9v8bYahZcFBLue5rPC3.md","filePath":"logistics/src/page-feO9v8bYahZcFBLue5rPC3.md","lastUpdated":null}'),r={name:"src/page-feO9v8bYahZcFBLue5rPC3.md"};function n(o,e,c,l,p,d){return t(),s("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="管道及传送带的分层现象" aria-hidden="true"></span><h1 id="layering-of-pipes-and-transport-belts" tabindex="-1">Layering of Pipes and Transport Belts <a class="header-anchor" href="#layering-of-pipes-and-transport-belts" aria-label="Permalink to &quot;Layering of Pipes and Transport Belts&quot;">​</a></h1><blockquote><p>Source page ID: <code>feO9v8bYahZcFBLue5rPC3</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=feO9v8bYahZcFBLue5rPC3" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>As is well known, drawing pipes from high to low ground allows multiple pipe layers in the same location. Belts show a similar effect, with high and low positions not coinciding, as shown:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-557ca6b04d490a19.q90-e7f1e7d354f3408e.webp" alt="Layering of Pipes and Transport Belts"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4d22404c1bed8bf4.q90-c43ba2bd42b372a9.webp" alt="Layering of Pipes and Transport Belts"></p><p>In the second image, the belt and Planting Unit occupy different layers without a placement conflict: the Planting Unit is not red. However, the location is outside the permitted area, preventing placement for testing.</p><p>Special behavior caused by different pipe layers should also be recorded, such as stacking and behavior when connecting splitters/convergers: priority? Round-robin servicing?</p></div>',1)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
